/** Explicit opt-in qualification of a dedicated staging bucket. Never reuses S3_* credentials. */
import assert from "node:assert/strict";
import { createHash, randomBytes, randomUUID } from "node:crypto";
import { mkdirSync, writeFileSync } from "node:fs";
import { S3Client, GetBucketCorsCommand, GetBucketLifecycleConfigurationCommand, DeleteObjectCommand } from "@aws-sdk/client-s3";
import { normalizeStorageBucket, storageEndpointUrl } from "../lib/storage-policy";
const bucket=normalizeStorageBucket(process.env.QA_S3_BUCKET||""), endpoint=storageEndpointUrl(process.env.QA_S3_ENDPOINT||"");
if(!/(?:^|[-_.])(qa|staging|test)(?:[-_.]|$)/i.test(bucket) || process.env.QA_CONFIRM_DISPOSABLE_BUCKET!==bucket)throw new Error("A dedicated QA/staging bucket and exact confirmation are required");
if(process.env.S3_BUCKET || process.env.S3_ENDPOINT || process.env.DATABASE_URL)throw new Error("Do not supply application or production credentials");
const accessKeyId=process.env.QA_S3_ACCESS_KEY_ID||"",secretAccessKey=process.env.QA_S3_SECRET_ACCESS_KEY||"",origin=new URL(process.env.QA_UPLOAD_ORIGIN||"");
if(!accessKeyId || !secretAccessKey || origin.protocol!=="https:" || origin.origin!==process.env.QA_UPLOAD_ORIGIN)throw new Error("Dedicated credentials and exact HTTPS browser origin required");
Object.assign(process.env,{S3_ENDPOINT:endpoint.toString(),S3_BUCKET:bucket,S3_ACCESS_KEY_ID:accessKeyId,S3_SECRET_ACCESS_KEY:secretAccessKey,S3_REGION:process.env.QA_S3_REGION||"auto",S3_FORCE_PATH_STYLE:process.env.QA_S3_FORCE_PATH_STYLE||"true"});
const client=new S3Client({endpoint:endpoint.toString(),region:process.env.S3_REGION,forcePathStyle:process.env.S3_FORCE_PATH_STYLE!=="false",credentials:{accessKeyId,secretAccessKey},maxAttempts:2,requestChecksumCalculation:"WHEN_REQUIRED",responseChecksumValidation:"WHEN_REQUIRED"});
const t=await import("../lib/railway-direct-upload");
const id=randomUUID(), key=`private/video-source/qa-capability-${id}/probe/mp-${id}.mp4`, legacyKey=`private/video-source/qa-capability-${id}/probe/legacy.mp4`;
const checks:string[]=[], pass=(text:string)=>{checks.push(text);console.log("PASS S3 QUALIFICATION",text);};
let uploadId:string|undefined, error:unknown, cleanupFailed=false;
const signal=AbortSignal.timeout(120000);
try{
 const lifecycle=await client.send(new GetBucketLifecycleConfigurationCommand({Bucket:bucket}),{abortSignal:signal});
 assert.ok(lifecycle.Rules?.some(rule=>rule.Status==="Enabled" && Number(rule.AbortIncompleteMultipartUpload?.DaysAfterInitiation)>0
  && Number(rule.AbortIncompleteMultipartUpload?.DaysAfterInitiation)<=7 && !rule.Filter?.Tag && !rule.Filter?.And
  && !rule.Filter?.ObjectSizeGreaterThan && !rule.Filter?.ObjectSizeLessThan
  && key.startsWith(rule.Filter?.Prefix || rule.Prefix || "")),"Lifecycle must abort orphaned multipart uploads for this prefix within seven days");
 const cors=await client.send(new GetBucketCorsCommand({Bucket:bucket}),{abortSignal:signal});
 assert.ok(cors.CORSRules?.some(rule=>rule.AllowedOrigins?.includes(origin.origin) && rule.AllowedMethods?.includes("PUT")
  && ["content-type","x-amz-checksum-sha256","if-none-match"].every(name=>rule.AllowedHeaders?.some(value=>value==="*" || value.toLowerCase()===name))),"Staging origin and signed browser headers must be allowed explicitly in CORS");
 pass("bucket lifecycle covers abandoned initiation and CORS allows the exact staging origin and signed headers");
 const body=randomBytes(64), sum=createHash("sha256").update(body).digest("base64");
 uploadId=await t.startMultipartUpload(key,"video/mp4",id,signal);
 const part=await t.signMultipartPart(key,uploadId,1,body.length,sum);
 const put=async(data:Uint8Array,headers:Record<string,string>)=>fetch(part.uploadUrl,{method:"PUT",headers,body:new Uint8Array(data),signal});
 for(const response of [await put(randomBytes(65),part.headers),await put(body,{...part.headers,"x-amz-checksum-sha256":createHash("sha256").update("bad").digest("base64")}),await put(randomBytes(64),part.headers)]){
  assert.ok([400,403].includes(response.status),"provider must reject altered size/checksum/body before publication");await response.body?.cancel();
 }
 const accepted=await put(body,part.headers);assert.equal(accepted.status,200);await accepted.body?.cancel();
 const parts=await t.listMultipartParts(key,uploadId,signal);assert.equal(parts?.length,1);assert.equal(parts![0].size,body.length);assert.equal(parts![0].checksum,sum);
 await t.completeMultipartUpload(key,uploadId,parts!,body.length,signal);const head=await t.headMultipartUpload(key,signal);
 assert.equal(head?.size,body.length);assert.equal(head?.checksum,t.multipartCompositeChecksum([sum]));assert.equal(head?.sessionId,id);
 pass("provider enforces signed lengths and SHA256, returns checked parts and verifies a conditional completed object");
 const replay=await put(body,part.headers);assert.ok([400,404].includes(replay.status));await replay.body?.cancel();
 const second=await t.startMultipartUpload(key,"video/mp4",id,signal);
 try{const signed=await t.signMultipartPart(key,second,1,body.length,sum);const sent=await fetch(signed.uploadUrl,{method:"PUT",headers:signed.headers,body:new Uint8Array(body),signal});assert.equal(sent.status,200);await sent.body?.cancel();
  const stored=await t.listMultipartParts(key,second,signal);await assert.rejects(t.completeMultipartUpload(key,second,stored!,body.length,signal),err=>(err as {$metadata?:{httpStatusCode?:number}}).$metadata?.httpStatusCode===412);
 }finally{await t.abortMultipartUpload(key,second,signal);}
 const url=await t.createDirectUploadUrl(legacyKey,"video/mp4",body.length,60),headers={"content-type":"video/mp4","if-none-match":"*"};
 const first=await fetch(url,{method:"PUT",headers,body:new Uint8Array(body),signal});assert.equal(first.status,200);await first.body?.cancel();
 const duplicate=await fetch(url,{method:"PUT",headers,body:new Uint8Array(body),signal});assert.equal(duplicate.status,412);await duplicate.body?.cancel();
 pass("completed part URLs cannot overwrite, conditional multipart completion rejects an occupied key, and legacy PUT is immutable");
}catch(caught){error=caught;}
finally{
 if(uploadId)try{await t.abortMultipartUpload(key,uploadId,AbortSignal.timeout(20000));}catch{cleanupFailed=true;}
 for(const objectKey of [key,legacyKey])try{await client.send(new DeleteObjectCommand({Bucket:bucket,Key:objectKey}),{abortSignal:AbortSignal.timeout(10000)});}catch{cleanupFailed=true;}
 client.destroy();
}
mkdirSync(".data",{recursive:true});writeFileSync(".data/qa-s3-live-report.json",JSON.stringify({qualified:!error&&!cleanupFailed,passed:checks.length,checks,cleanupFailed,checkedAt:new Date().toISOString(),providerFingerprint:createHash("sha256").update(JSON.stringify([endpoint.toString(),bucket,process.env.S3_REGION,process.env.S3_FORCE_PATH_STYLE])).digest("hex"),error:error?"provider_qualification_failed":null},null,2),{mode:0o600});
if(error||cleanupFailed)throw new Error("S3 staging qualification failed; multipart must remain disabled. Inspect the private provider-side diagnostics.");
